/** The Russian plural: one → n%10 = 1 and n%100 ≠ 11; few → n%10 in 2–4 and n%100 not in 12–14; many → the rest. */
const form = (count: string, one: string, few: string, many: string) => {
  const c = Number(count);
  if (c % 10 === 1 && c % 100 !== 11) return one;
  return c % 10 >= 2 && c % 10 <= 4 && (c % 100 < 12 || c % 100 > 14) ? few : many;
};
const n = (count: string, one: string, few: string, many: string) => `${count} ${form(count, one, few, many)}`;

/** Phrases with a number or a name in them. */
/** The nonlinear solve's and the buckling's messages, translated inside the notes that carry them (S5). */
const S5_MESSAGES: [RegExp, (m: RegExpExecArray) => string][] = [
  [/^Second order: unstable, the loads are past the critical ones \(αcr < 1\)\.$/, () => "Второй порядок: конструкция неустойчива, нагрузки превысили критические (αcr < 1)."],
  [/^A mechanism once 1 members? went slack: nothing holds node (\S+) \(([^)]*)\)\.$/, (m) => `Механизм после провисания 1 стержня: ничто не удерживает узел ${m[1]} (${m[2]}).`],
  [/^A mechanism once (\d+) members? went slack: nothing holds node (\S+) \(([^)]*)\)\.$/, (m) => `Механизм после провисания ${n(m[1], 'стержня', 'стержней', 'стержней')}: ничто не удерживает узел ${m[2]} (${m[3]}).`],
  [/^A mechanism once 1 members? went slack and (\d+) supports? lifted: nothing holds node (\S+) \(([^)]*)\)\.$/, (m) => `Механизм после провисания 1 стержня и отрыва ${n(m[1], 'опоры', 'опор', 'опор')}: ничто не удерживает узел ${m[2]} (${m[3]}).`],
  [/^A mechanism once (\d+) members? went slack and (\d+) supports? lifted: nothing holds node (\S+) \(([^)]*)\)\.$/, (m) => `Механизм после провисания ${n(m[1], 'стержня', 'стержней', 'стержней')} и отрыва ${n(m[2], 'опоры', 'опор', 'опор')}: ничто не удерживает узел ${m[3]} (${m[4]}).`],
  [/^A mechanism at node (\S+) \(([^)]*)\)\.$/, (m) => `Механизм в узле ${m[1]} (${m[2]}).`],
  [/^The one-way members and supports did not settle: they go back to states already tried\.$/, () => "Односторонние стержни и опоры не установились: они возвращаются к уже проверенным состояниям."],
  [/^Not settled in (\d+) iterations\.$/, (m) => `Нет сходимости за ${n(m[1], 'итерацию', 'итерации', 'итераций')}.`],
  [/^No buckling under these loads: the geometric stiffness only stiffens\.$/, () => "При этих нагрузках потери устойчивости нет: геометрическая жёсткость только увеличивает жёсткость."],
  [/^No buckling mode: the compressed bars are held by what is round them\.$/, () => "Формы потери устойчивости нет: сжатые стержни удерживаются окружающими элементами."],
  [/^A mechanism in its last states\.$/, () => "Механизм в последних состояниях."],
];
function s5msg(text: string): string {
  for (const [re, f] of S5_MESSAGES) { const x = re.exec(text); if (x) return f(x); }
  return text;
}

/** S5d: the parts of the imperfections', sheeting's and θ notes that vary. */
function s5dSeg(t: string): string {
  const a = /^φ up to 1\/(\d+) along (X|Y)(?: \(m = ([\d.]+)\))?$/.exec(t);
  if (a) return a[3] ? `φ до 1/${a[1]} вдоль ${a[2]} (m = ${a[3]})` : `φ до 1/${a[1]} вдоль ${a[2]}`;
  const b = /^no column along (X|Y)$/.exec(t);
  return b ? `нет колонны вдоль ${b[1]}` : t;
}
